#!/usr/bin/env python3
import zipfile
import json
import re
from lxml import etree

# 1. Read JSON data
with open('/root/inventory_data.json', 'r', encoding='utf-8') as f:
    data = json.load(f)

placeholder_re = re.compile(r'\{\{([^{}]+)\}\}')

HP_NS = 'http://www.hancom.co.kr/hwpml/2010/HWPML'
P_TAG = f'{{{HP_NS}}}p'
LINESEG_TAG = f'{{{HP_NS}}}linesegarray'


def replace_text(text):
    if text is None:
        return text, False
    new_text = placeholder_re.sub(lambda m: str(data.get(m.group(1), m.group(0))), text)
    return new_text, new_text != text


with zipfile.ZipFile('/root/inventory_report_ready.hwpx', 'w', compression=zipfile.ZIP_DEFLATED) as zout:
    # mimetype MUST be first entry and stored uncompressed
    mimetype_info = zipfile.ZipInfo('mimetype')
    mimetype_info.compress_type = zipfile.ZIP_STORED
    zout.writestr(mimetype_info, b'application/hwp+zip')

    with zipfile.ZipFile('/root/inventory_report_template.hwpx', 'r') as zin:
        for info in zin.infolist():
            raw = zin.read(info.filename)
            try:
                text = raw.decode('utf-8')
            except UnicodeDecodeError:
                text = None

            if text is not None and '{{' in text:
                tree = etree.fromstring(raw)

                # Register all namespaces to preserve prefixes like hp:, ha:, hc: etc.
                for prefix, uri in tree.nsmap.items():
                    if prefix is not None:
                        etree.register_namespace(prefix, uri)
                    else:
                        etree.register_namespace('', uri)

                modified_ps = set()

                for elem in tree.iter():
                    if elem.text is not None and '{{' in elem.text:
                        new_text, changed = replace_text(elem.text)
                        if changed:
                            elem.text = new_text
                            node = elem
                            while node is not None:
                                if node.tag == P_TAG:
                                    modified_ps.add(node)
                                    break
                                node = node.getparent()

                    if elem.tail is not None and '{{' in elem.tail:
                        new_tail, changed = replace_text(elem.tail)
                        if changed:
                            elem.tail = new_tail
                            node = elem
                            while node is not None:
                                if node.tag == P_TAG:
                                    modified_ps.add(node)
                                    break
                                node = node.getparent()

                # Remove stale lineSegArray (linesegarray) caches from modified paragraphs
                for p in modified_ps:
                    for child in list(p):
                        if child.tag == LINESEG_TAG:
                            p.remove(child)

                out_bytes = etree.tostring(tree, encoding='UTF-8', xml_declaration=True)
                zout.writestr(info.filename, out_bytes)
            else:
                # Copy unchanged; skip any input mimetype because we already wrote our own first
                if info.filename != 'mimetype':
                    zout.writestr(info.filename, raw)

print('Done: /root/inventory_report_ready.hwpx')

